class C:
 def __init__(self,w=1600,h=1000):
  self.w=w;self.h=h;self.im=Image.new('RGB',(w*2,h*2),'white');self.d=ImageDraw.Draw(self.im);self.svg=[]
 def rect(self,x,y,w,h,fill=LIGHT,stroke=TEAL,r=15,dash=False):
  self.d.rounded_rectangle((x*2,y*2,(x+w)*2,(y+h)*2),radius=r*2,fill=fill,outline=stroke,width=4)
  self.svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="{stroke}" stroke-width="2"'+(' stroke-dasharray="9 7"' if dash else '')+'/>')
 def text(self,x,y,text,size=36,color=NAVY,width=None):
  for i,line in enumerate(text.split('\n')):
   font=ImageFont.truetype(FONT,size*2);latin=bool(re.fullmatch(r'[\x00-\x7f]+',line));direction='ltr' if latin else 'rtl'; yy=y+i*size*1.4
   bbox=self.d.textbbox((0,0),line,font=font,direction=direction)
   if width and (bbox[2]-bbox[0])/2>width-20:checks.append({'text':line,'actual':(bbox[2]-bbox[0])/2,'available':width-20})
   self.d.text((x*2,yy*2),line,font=font,fill=color,anchor='mm',direction=direction,language='fa' if not latin else 'en')
   self.svg.append(f'<text x="{x}" y="{yy}" fill="{color}" font-size="{size}" font-family="Vazirmatn,Tahoma,sans-serif" text-anchor="middle" dominant-baseline="central" direction="{direction}" style="unicode-bidi:plaintext">{html.escape(line)}</text>')
 def box(self,x,y,w,h,text,fill=LIGHT,size=36,stroke=TEAL):
  self.rect(x,y,w,h,fill,stroke);self.text(x+w/2,y+h/2-(len(text.split('\n'))-1)*size*.7,text,size,width=w)
 def path(self,pts,color=TEAL,width=4,arrow=False,dash=False):
  self.d.line([(int(x*2),int(y*2)) for x,y in pts],fill=color,width=width*2,joint='curve')
  self.svg.append('<polyline points="'+' '.join(f'{x},{y}' for x,y in pts)+f'" fill="none" stroke="{color}" stroke-width="{width}"'+(' stroke-dasharray="10 8"' if dash else '')+'/>')
  if arrow:
   a,b=pts[-2:];ang=math.atan2(b[1]-a[1],b[0]-a[0]);tri=[b,(b[0]-19*math.cos(ang-.45),b[1]-19*math.sin(ang-.45)),(b[0]-19*math.cos(ang+.45),b[1]-19*math.sin(ang+.45))]
   self.d.polygon([(int(x*2),int(y*2)) for x,y in tri],fill=color);self.svg.append('<polygon points="'+' '.join(f'{x},{y}' for x,y in tri)+f'" fill="{color}"/>')
 def arrow(self,x1,y1,x2,y2,color=TEAL):self.path([(x1,y1),(x2,y2)],color,arrow=True)
 def note(self,t):self.text(self.w/2,self.h-45,t,29,GRAY,width=self.w-60)
 def save(self,id,title,chapter,source,fig=None,page=None,anchor=None,kind='adapted',printed=None):
  self.im.save(OUT/(id+'.png'),dpi=(400,400));(OUT/(id+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{self.w}" height="{self.h}" viewBox="0 0 {self.w} {self.h}"><rect width="100%" height="100%" fill="white"/>'+''.join(self.svg)+'</svg>')
  manifest.append(dict(id=id,title=title,chapter=chapter,source=source,source_figure=fig,pdf_page=page,printed_page=printed,anchor=anchor,kind=kind,png='07-Figures/'+id+'.png',svg='07-Figures/'+id+'.svg',width=self.w,height=self.h))
